#include <stdio.h>
#include "ui_util.h"

bool screen_is_loading(lv_obj_t *scr)
{
#if LVGL_VERSION_MAJOR == 8
    lv_obj_t *act_scr = lv_scr_act();
    lv_disp_t *d = lv_obj_get_disp(scr);
    if (d->prev_scr == NULL && (d->scr_to_load == NULL || d->scr_to_load == act_scr))
        return false;
    else
        return true;
#else
    return false;
#endif
}

void ui_style_init(lv_style_t *style)
{
  if (style->prop_cnt >= 1)
    lv_style_reset(style);
  else
    lv_style_init(style);
}

lv_font_t *ui_font_init(char *path, int size) {
#if LVGL_VERSION_MAJOR == 8
    static lv_ft_info_t info;
    info.name = path;
    info.weight = size;
    info.style = FT_FONT_STYLE_NORMAL;
    info.mem = NULL;
    if (!lv_ft_font_init(&info))
        return NULL;
    return info.font;
#else
    lv_font_t *font = lv_freetype_font_create(path,
                                              LV_FREETYPE_FONT_RENDER_MODE_BITMAP,
                                              size,
                                              LV_FREETYPE_FONT_STYLE_NORMAL);
    return font;
#endif //LVGL_VERSION_MAJOR
}


int count_png_files(const char *path)
{
    lv_fs_dir_t dir;
    lv_fs_res_t res;
    int png_count = 0;
    char fn[256];
    
    /* 打开目录 */
    res = lv_fs_dir_open(&dir, path);
    if (res != LV_FS_RES_OK) {
        LV_LOG_ERROR("Failed to open dir: %s, res: %d", path, res);
        return -1;
    }

    /* 遍历目录 */
    while (1) {
        res = lv_fs_dir_read(&dir, fn, sizeof(fn));
        if (res != LV_FS_RES_OK) {
            LV_LOG_ERROR("Dir read error: %d", res);
            break;
        }
        
        /* 读取结束（空字符串表示遍历完成）*/
        if (fn[0] == '\0') {
            break;
        }
        
        /* 跳过 . 和 .. */
        if (strcmp(fn, ".") == 0 || strcmp(fn, "..") == 0) {
            continue;
        }
        
        // 检查是否是.png 结尾
        size_t len = strlen(fn);
        if (len > 4) {
            const char *ext = fn + len - 4;
            if (strstr(ext, ".png") ) {
                png_count++;
                LV_LOG_INFO("Found PNG: %s", fn);
            }
        }
    }
    
    /* 关闭目录 */
    lv_fs_dir_close(&dir);
    
    return png_count;
}
